    // 삭제(최소값): O(log n)
    public int extractMin() {
        int min = heap[0];
        heap[0] = heap[--size];
        siftDown(0);
        return min;
    }

    private void siftDown(int index) {
        while (2 * index + 1 < size) {
            int child = 2 * index + 1;
            if (child + 1 < size && heap[child + 1] < heap[child]) {
                child++;
            }
            if (heap[index] > heap[child]) {
                swap(index, child);
                index = child;
            } else break;
        }
    }
}
```

